#!/usr/bin/env node
/**
 * build-injury-anatomy.js — the body map's data → data/injury-anatomy.json
 *
 * WHAT THIS IS FOR
 * A reader who wants to understand a knee injury does not want a table of
 * injury types sorted alphabetically. He wants to point at a knee. So the site
 * gets a body map, and this assembles what each region can honestly say.
 *
 * WHERE EVERY NUMBER COMES FROM, AND WHY NONE OF IT IS INVENTED
 *
 * This site's first rule is that data files are generated by a committed script
 * and never hand-typed, and its second is that nothing is published without a
 * source. A body map is exactly where those rules come under pressure: it is
 * very easy, and very tempting, to write "MCL Grade II — 4 to 6 weeks" from
 * general knowledge. That would be a number with no source on a page that
 * promises none of those exist.
 *
 * So each region carries three separate layers, and each is labelled:
 *
 *   FREQUENCY   counted from data/injuries.json — the official NFL injury
 *               reports for our own pool. "How often does this actually happen
 *               to the players you care about."
 *   RECOVERY    from data/injury-curves.json, derived from those same reports:
 *               median games missed, and how players performed on return
 *               against their own pre-injury baseline.
 *   RESEARCH    from data/injury-research.json, the hand-written sourced
 *               layer — return rates, reinjury risk, career impact. It covers
 *               SEVEN injuries. Everything else gets nothing, and says so.
 *
 * NAMED SUB-INJURIES ARE SCAFFOLDED, NOT FILLED. Each region lists the
 * conditions that genuinely occur there, and a `research` key that is either a
 * pointer into the sourced file or null. A null is HONEST: the page shows the
 * name and states that we have no sourced detail for it, rather than printing
 * a plausible timeline nobody can check. Filling one in means adding a sourced
 * entry to injury-research.json, the same standing as medicals.json.
 *
 *   node scripts/build-injury-anatomy.js
 *   node scripts/build-injury-anatomy.js --dry
 */

const fs = require('fs');
const path = require('path');

const DATA = path.join(__dirname, '..', 'data');
const OUT = path.join(DATA, 'injury-anatomy.json');
const read = (f) => JSON.parse(fs.readFileSync(path.join(DATA, f), 'utf8'));

/**
 * The regions of the body a reader can point at, and what belongs to each.
 *
 * `parts` are the strings the official injury report actually uses — taken from
 * the real data, not guessed, so the counts are countable. `conditions` are the
 * named injuries that occur at that region; `research` points into
 * injury-research.json where we have a sourced entry and is null where we do
 * not. A null is a gap the page states, not one it fills.
 *
 * `curve` names the bucket in injury-curves.json, which is grouped at the level
 * a reader reasons about rather than the level the report is written at.
 */
const REGIONS = {
  head: {
    label: 'Head & neck',
    parts: ['Concussion', 'Head', 'Neck'],
    curve: 'Concussion',
    conditions: [
      { name: 'Concussion', research: 'concussion', note: 'Return is governed by a league protocol, not by how a player feels.' },
      { name: 'Neck strain', research: null },
      { name: 'Stinger / burner', research: null, note: 'A nerve injury, usually brief, and rarely reported as such.' },
    ],
  },
  shoulder: {
    label: 'Shoulder',
    parts: ['Shoulder', 'Clavicle', 'Collarbone', 'AC joint'],
    curve: 'Shoulder',
    conditions: [
      { name: 'AC joint sprain', research: null, note: 'The common one. Graded I to VI; the low grades play through it.' },
      { name: 'Labrum tear', research: null },
      { name: 'Rotator cuff strain', research: null },
      { name: 'Dislocation', research: null },
    ],
  },
  arm: {
    label: 'Arm, elbow & hand',
    parts: ['Elbow', 'Arm', 'Forearm', 'Biceps', 'Triceps', 'Wrist', 'Hand', 'Finger', 'Thumb'],
    curve: 'Arm / Hand',
    conditions: [
      { name: 'Hand or finger fracture', research: null, note: 'Position decides everything here — a lineman plays, a receiver does not.' },
      { name: 'Wrist sprain', research: null },
      { name: 'Elbow hyperextension', research: null },
      { name: 'Biceps or triceps tear', research: null },
    ],
  },
  core: {
    label: 'Ribs, chest & core',
    parts: ['Ribs', 'Rib', 'Chest', 'Abdomen', 'Oblique', 'Pectoral'],
    curve: 'Ribs / Core',
    conditions: [
      { name: 'Rib fracture or contusion', research: null },
      { name: 'Oblique strain', research: null },
      { name: 'Pectoral tear', research: null },
    ],
  },
  back: {
    label: 'Back',
    parts: ['Back', 'Spine'],
    curve: 'Back / Neck',
    conditions: [
      { name: 'Lower back strain', research: null },
      { name: 'Disc injury', research: null },
    ],
  },
  hip: {
    label: 'Hip & groin',
    parts: ['Hip', 'Groin', 'Abductor', 'Adductor', 'Glute'],
    curve: 'Hip / Groin',
    conditions: [
      { name: 'Groin / adductor strain', research: null },
      { name: 'Hip flexor strain', research: null },
      { name: 'Hip labrum tear', research: null },
    ],
  },
  thigh: {
    label: 'Hamstring, quad & thigh',
    parts: ['Hamstring', 'Quadricep', 'Thigh', 'Leg'],
    curve: 'Hamstring',
    conditions: [
      { name: 'Hamstring strain', research: 'hamstring', note: 'The most re-injured muscle in football. Coming back early is how one becomes three.' },
      { name: 'Quad strain', research: null },
      { name: 'Thigh contusion', research: null },
    ],
  },
  knee: {
    label: 'Knee',
    parts: ['Knee', 'ACL', 'MCL', 'PCL', 'Meniscus'],
    curve: 'Knee',
    conditions: [
      { name: 'ACL tear', research: 'acl', note: 'The one that changes a career, not just a season.' },
      { name: 'PCL tear', research: 'pcl' },
      { name: 'MCL sprain', research: null, note: 'Graded I to III. The low grades are weeks, not months, and are often played through.' },
      { name: 'LCL sprain', research: null },
      { name: 'Meniscus tear', research: null, note: 'A trim and a repair are different operations with very different timelines.' },
      { name: 'Patellar dislocation', research: null },
    ],
  },
  calf: {
    label: 'Calf & shin',
    parts: ['Calf', 'Shin', 'Fibula', 'Tibia'],
    curve: 'Calf / Quad',
    conditions: [
      { name: 'Calf strain', research: null },
      { name: 'Shin splints', research: null },
    ],
  },
  ankle: {
    label: 'Ankle',
    parts: ['Ankle'],
    curve: 'Ankle',
    conditions: [
      { name: 'High ankle sprain', research: 'high_ankle', note: 'Different injury from a rolled ankle, and several times the absence.' },
      { name: 'Low ankle sprain', research: null },
      { name: 'Achilles tear', research: 'achilles', note: 'Technically the heel, but it presents and is reported at the ankle.' },
    ],
  },
  foot: {
    label: 'Foot & toe',
    parts: ['Foot', 'Toe', 'Plantar', 'Heel', 'Achilles'],
    curve: 'Foot / Toe',
    conditions: [
      { name: 'Turf toe', research: 'turf_toe', note: 'Sounds minor and is not — the grade-3 version ends seasons.' },
      { name: 'Lisfranc injury', research: null },
      { name: 'Plantar fasciitis', research: null },
      { name: 'Metatarsal fracture', research: null },
    ],
  },
};

function main() {
  const dry = process.argv.includes('--dry');
  const injuries = read('injuries.json');
  const curves = read('injury-curves.json');
  const research = read('injury-research.json');
  const pool = read('players.json');
  const inPool = new Set(pool.map(p => p.id));

  // Count how often each body part actually appears, and how many of OUR
  // players it has happened to. Counted rather than asserted.
  const partCounts = {};
  const partPlayers = {};
  let episodes = 0;
  for (const [id, seasons] of Object.entries(injuries)) {
    if (id === 'meta' || !inPool.has(id)) continue;
    for (const [year, v] of Object.entries(seasons)) {
      if (!/^\d{4}$/.test(year)) continue;
      for (const e of v.episodes || []) {
        if (!e.part) continue;
        episodes++;
        partCounts[e.part] = (partCounts[e.part] || 0) + 1;
        (partPlayers[e.part] = partPlayers[e.part] || new Set()).add(id);
      }
    }
  }

  const out = {
    meta: {
      builtBy: 'scripts/build-injury-anatomy.js',
      builtAt: new Date().toISOString(),
      layers: {
        frequency: 'counted from data/injuries.json — the official NFL injury reports for this pool',
        recovery: 'from data/injury-curves.json, derived from those same reports',
        research: 'from data/injury-research.json, the hand-written sourced layer — SEVEN injuries only',
      },
      caveats: [
        'A body part on an injury report is what a team chose to declare. Teams are '
        + 'inconsistent about it, and a player placed on IR drops off the report entirely — '
        + 'so the counts here understate the season-ending cases rather than capturing them.',
        'A named condition without a research entry is listed because it genuinely occurs at '
        + 'that region, NOT because we have data on it. The page says so rather than printing '
        + 'a timeline nobody can check.',
        'Recovery figures are the median across this pool over three seasons, not a prognosis '
        + 'for any individual. Sample sizes are stated and several are small.',
      ],
      totalEpisodes: episodes,
    },
    regions: {},
  };

  // Teams write the same body part several ways — "Shoulder", "right Shoulder",
  // "Right Shoulder" — and an exact match drops every side-prefixed one on the
  // floor. Thirteen shoulder episodes were sitting in the unmapped list purely
  // because somebody typed a side. Which side it is has never mattered to a
  // reader pointing at a body map.
  const canon = (s) => String(s || '')
    .toLowerCase()
    .replace(/\b(left|right|l|r)\b/g, '')
    .replace(/[^a-z ]/g, '')
    .replace(/\s+/g, ' ')
    .trim();

  const byCanon = {};
  for (const [part, n] of Object.entries(partCounts)) {
    const c = canon(part);
    if (!c) continue;
    (byCanon[c] = byCanon[c] || []).push(part);
  }

  const unmatched = new Set(Object.keys(partCounts));
  for (const [key, def] of Object.entries(REGIONS)) {
    let count = 0;
    const players = new Set();
    const partsSeen = [];
    for (const wanted of def.parts) {
      for (const part of (byCanon[canon(wanted)] || [])) {
        const n = partCounts[part] || 0;
        if (!n) continue;
        partsSeen.push({ part, episodes: n, players: partPlayers[part].size });
        count += n;
        for (const p of partPlayers[part]) players.add(p);
        unmatched.delete(part);
      }
    }

    const curve = def.curve && curves.types[def.curve] ? curves.types[def.curve] : null;

    out.regions[key] = {
      label: def.label,
      // Frequency, counted.
      episodes: count,
      players: players.size,
      shareOfAll: episodes ? +(100 * count / episodes).toFixed(1) : null,
      reportedAs: partsSeen.sort((a, b) => b.episodes - a.episodes),
      // Recovery, derived.
      recovery: curve ? {
        source: 'injury-curves.json',
        bucket: def.curve,
        absences: curve.absences,
        players: curve.players,
        medianGamesMissed: curve.medianMissed,
        baselinePpg: curve.medianBaseline,
        returnCurve: curve.curve,
        examples: (curve.examples || []).slice(0, 4),
      } : null,
      // The named conditions, with research attached only where it exists.
      conditions: def.conditions.map(c => {
        const r = c.research ? research[c.research] : null;
        return {
          name: c.name,
          note: c.note || null,
          research: r ? {
            key: c.research,
            returnRate: r.returnRate,
            returnRateLabel: r.returnRateLabel,
            avgReturn: r.avgReturn,
            reinjuryLabel: r.reinjuryLabel,
            performanceLabel: r.performanceLabel,
            careerImpact: r.careerImpact,
            fantasyImpact: r.fantasyImpact,
          } : null,
          // Stated on the record, so the page never has to infer it.
          hasSourcedDetail: !!r,
        };
      }),
    };
  }

  // Anything the report says that no region claims. Reported rather than
  // dropped: a body part appearing 40 times and belonging to no region is a
  // hole in the map, not a rounding error.
  const orphans = [...unmatched]
    .filter(p => !/not injury related|illness|rest|personal|coach/i.test(p))
    .map(p => ({ part: p, episodes: partCounts[p] }))
    .sort((a, b) => b.episodes - a.episodes);
  out.meta.unmappedParts = orphans;

  const covered = Object.values(out.regions).reduce((s, r) => s + r.episodes, 0);
  out.meta.coverage = { mappedEpisodes: covered, totalEpisodes: episodes,
    pct: episodes ? +(100 * covered / episodes).toFixed(1) : null };

  console.log(`[anatomy] ${episodes} reported episodes across the pool`);
  for (const [key, r] of Object.entries(out.regions)) {
    const sourced = r.conditions.filter(c => c.hasSourcedDetail).length;
    console.log(`  ${r.label.padEnd(24)} ${String(r.episodes).padStart(4)} episodes · ${r.players} players · `
      + `${sourced}/${r.conditions.length} conditions sourced`
      + (r.recovery ? ` · median ${r.recovery.medianGamesMissed} games out` : ' · no curve'));
  }
  console.log(`[anatomy] mapped ${covered}/${episodes} (${out.meta.coverage.pct}%)`);
  if (orphans.length) {
    console.log(`[anatomy] ${orphans.length} body part(s) belong to no region: `
      + orphans.slice(0, 8).map(o => `${o.part} (${o.episodes})`).join(', '));
  }

  if (dry) { console.log('[anatomy] dry run — nothing written'); return; }
  fs.writeFileSync(OUT, JSON.stringify(out, null, 2) + '\n');
  console.log(`[anatomy] wrote data/injury-anatomy.json (${Math.round(fs.statSync(OUT).size / 1024)}KB)`);
}

try { main(); } catch (e) { console.error('[anatomy] FAILED:', e.message); process.exit(1); }
